const mongoose = require('mongoose');

/**
 * PriceHistory Schema
 * Stores historical records of dynamic price changes and recommendations.
 * As defined in the project specification:
 * - productId: Reference to the Product in the Products collection
 * - oldPrice: Base / previous price of the product
 * - recommendedPrice: The new price recommended by the rule engine
 * - reason: Explanation of the rules triggered
 * - aiExplanation: Natural language explanation generated by AI or fallback engine
 * - appliedRules: List of rule objects applied during calculation
 * - createdAt: Timestamp when this recommendation was logged
 */
const priceHistorySchema = new mongoose.Schema(
  {
    productId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Product', // Reference to the Product model
      required: [true, 'Product ID is required for price history record'],
    },
    oldPrice: {
      type: Number,
      required: [true, 'Old price is required'],
      min: [0, 'Old price cannot be negative'],
    },
    recommendedPrice: {
      type: Number,
      required: [true, 'Recommended price is required'],
      min: [0, 'Recommended price cannot be negative'],
    },
    reason: {
      type: String,
      required: [true, 'Reason for price recommendation is required'],
      trim: true,
    },
    aiExplanation: {
      type: String,
      trim: true,
    },
    appliedRules: [
      {
        rule: String,
        name: String,
        adjustmentPercentage: Number,
      },
    ],
  },
  {
    timestamps: true, // Automatically provides createdAt and updatedAt
  }
);

// Index on productId and createdAt for high-speed chronological history queries
priceHistorySchema.index({ productId: 1, createdAt: -1 });

const PriceHistory = mongoose.model('PriceHistory', priceHistorySchema);

module.exports = PriceHistory;
